"8 semesters. Tuition RM 90,000 less a special fee discount of RM 30,000 = RM 60,000 (RM 7,500 a semester). Total RM 64,000 with refundable caution deposit RM 2,000 and resource fee RM 2,000 (RM 500 a year). Non-refundable application fee RM 300 (direct intake) / RM 150 (progression) (MUCM 2026 Fee Schedule).":"共 8 个学期。学费 RM 90,000，扣除特别优惠 RM 30,000 后为 RM 60,000（每学期 RM 7,500）。连同可退还押金 RM 2,000 及资源费 RM 2,000（每年 RM 500），总额 RM 64,000。不可退还的报名费 RM 300（直接入学）／RM 150（升读）（MUCM 2026 学费表）。",
"8 semesters. Tuition RM 90,000 less a special fee discount of RM 30,000 = RM 60,000 (RM 7,500 a semester). Total RM 64,000 with refundable caution deposit RM 2,000 and resource fee RM 2,000 (RM 500 a year). Non-refundable application fee RM 300 (direct intake) / RM 150 (progression) (MUCM 2026 Fee Schedule). The brochure says the launch fee includes a RM 10,000 Pioneer Discount and a 25% Silver Jubilee Discount.":"共 8 个学期。学费 RM 90,000，扣除特别优惠 RM 30,000 后为 RM 60,000（每学期 RM 7,500）。连同可退还押金 RM 2,000 及资源费 RM 2,000（每年 RM 500），总额 RM 64,000。不可退还的报名费 RM 300（直接入学）／RM 150（升读）（MUCM 2026 学费表）。简章说明首发学费已包括 RM 10,000 先锋优惠及 25% 银禧优惠。",
"9 semesters (3 a year). Tuition RM 90,000 less a special fee discount of RM 40,275 = RM 49,725. Total RM 52,225 with refundable caution deposit RM 1,000 and resource fee RM 1,500 (RM 500 a year). Non-refundable application fee RM 300 (direct intake) / RM 150 (progression) (MUCM 2026 Fee Schedule).":"共 9 个学期（每年 3 个学期）。学费 RM 90,000，扣除特别优惠 RM 40,275 后为 RM 49,725。连同可退还押金 RM 1,000 及资源费 RM 1,500（每年 RM 500），总额 RM 52,225。不可退还的报名费 RM 300（直接入学）／RM 150（升读）（MUCM 2026 学费表）。",
"A bond period is attached to the scholarship":"奖学金附带服务合约",
"A five-year dental degree. Semesters 1 to 4 cover pre-clinical theory and practice, including cadaver dissection; from semester 5 students treat patients at the on-site dental clinic, which sees over 30,000 patients a year.":"五年制牙科学位。第 1 至 4 学期为临床前理论与实践，包括大体解剖；从第 5 学期起，学生在校内牙科诊所为病人治疗，该诊所每年接诊超过 30,000 名病人。",
"A five-year medical degree in 10 semesters: pre-clerkship with cadaver dissection (semesters 1 to 4), junior clerkship (5 to 7), senior clerkship (8 to 9) and shadow housemanship (10). Over 1,500 patient beds are available for clinical experience through local hospitals and healthcare centres.":"五年制医科学位，共 10 个学期：临床前阶段，包括大体解剖（第 1 至 4 学期）、初级临床见习（第 5 至 7 学期）、高级临床实习（第 8 至 9 学期）及影子实习医生阶段（第 10 学期）。通过本地医院及医疗中心，提供超过 1,500 张病床作临床学习。",
"A one-year programme that prepares students for degrees in the health sciences, with grounding in biology, chemistry, physics, mathematics and study skills. It leads to degrees in Medicine, Dentistry, Pharmacy, Biomedical Science, Psychology, Allied Health, Optometry and Nursing.":"为期一年的课程，为修读健康科学学位做准备，打好生物、化学、物理、数学及学习技巧的基础。可升读医科、牙科、药剂、生物医学、心理学、辅助医疗、验光及护理等学位。",
"A research-oriented programme, accredited and recognised nationwide and globally.":"以研究为导向的课程，获国内及全球认证与承认。",
"A seamless pathway to EEE doctorate programme at XMUM or other renowned institutions worldwide.":"无缝衔接 XMUM 或全球其他知名院校的电气与电子工程博士课程。",
