"APU’s Bachelor of Science (Honours) in Actuarial Studies is a 3-year degree programme of full-time study. This programme is to develop students’ mathematical, statistical and analytical skills in addition to actuarial practices as preparation to become a qualified actuary. Actuaries work across several industries including life and general insurance, commercial and investment banking, pensions and healthcare, consulting firms, and public sector.":"APU 的精算学荣誉理学士（Bachelor of Science (Honours) in Actuarial Studies）是为期3年的全日制学位课程。本课程旨在培养学生的数学、统计与分析能力以及精算实务，为成为合格精算师做好准备。精算师的工作横跨多个行业，包括人寿与普通保险、商业与投资银行、退休金与医疗保健、咨询公司及公共部门。",
