"An Electrical or Electronic Engineer may be responsible for research, design, development, manufacturing and management of complex hardware and software systems and reliable, cost effective devices, including integrated electronic systems, renewable energy systems, generation, transmission and distribution of electrical power, instrumentation, manufacturing, microelectronics and photoelectronics. The programme provides a curriculum firmly grounded in electrical & electronic engineering fundamentals, and a study of both electronics fundamentals and electrical power systems including generation, transmission and distribution of electrical energy.":"电机或电子工程师可能负责复杂硬件与软件系统以及可靠、具成本效益之设备的研究、设计、开发、制造与管理，涵盖集成电子系统、可再生能源系统、电力的发电、输电与配电、仪器仪表、制造、微电子及光电子等领域。本课程的课程设置扎根于电机与电子工程基础，并同时研习电子学基础与电力系统，包括电能的发电、输电与配电。",
