"Animation is one of the fastest-growing industries worldwide, and its application facilitates exciting career opportunities in sectors like Advertising, Print media, TV production and Gaming. This programme aims to develop you as a creative animator, focusing on the fundamental animation processes and design skillsets in the creative industry while exploring animation techniques ranging from 2D traditional to CG animation. You will also gain production experience through industrial training as emphasis is placed on professional practice for greater employment prospects.":"动画是全球增长最快的行业之一，其应用为广告、印刷媒体、电视制作及游戏等领域带来令人兴奋的职业机会。本课程旨在将你培养成具创意的动画师，着重创意产业中基本的动画制作流程与设计技能，同时探索从传统二维到 CG 动画的各种动画技术。由于课程强调专业实践以提升就业前景，你也将通过工业实习获得制作经验。",
