"Artificial intelligence is an interdisciplinary field, covering disciplines like programming of intelligence, functionality of brain and industrial intelligence application, and there exists a huge demand for intelligence system programmers and designers. Xiamen University (XMU) has a very strong faculty in intelligence science with more than 23 academic staff, ranked among the top ten in China. With the balance between theories and practices, our programme at XMUM equips graduates with the necessary knowledge and skills to manage the development and research of computer and intelligence systems, and trains students' skills in analytical thinking, problem solving and management.":"人工智能是一门跨学科领域，涵盖智能编程、大脑功能及工业智能应用等学科，市场对智能系统程序员和设计师有巨大需求。厦门大学（XMU）在智能科学领域拥有非常强大的师资，学术人员超过23名，位列中国前十。XMUM 的本课程兼顾理论与实践，使毕业生具备管理计算机与智能系统开发和研究所需的知识与技能，并培养学生的分析思维、解决问题及管理能力。",
