"Computer engineering has emerged as a driving force addressing numerous global demands like smart grids, cognitive buildings and energy management; Computer Engineers bridge the gap between hardware and software. The programme provides a curriculum firmly grounded in Computer engineering fundamentals and a study of computer engineering which covers networking, database management, security systems, cloud infrastructure and data analytics. Areas covered include Digital Logic Design, Computer Networks, Embedded and Desktop Operating Systems, Microcontroller Selection and Programming, and Signal Processing.":"计算机工程已成为应对智能电网、认知建筑及能源管理等众多全球需求的推动力；计算机工程师连接硬件与软件之间的鸿沟。本课程的课程设置扎根于计算机工程基础，研习范围涵盖网络、数据库管理、安全系统、云基础设施及数据分析。涵盖领域包括数字逻辑设计、计算机网络、嵌入式与桌面操作系统、微控制器选型与编程，以及信号处理。",
