"Doctor of Philosophy in Computer Science and Technology":"计算机科学与技术博士",
"Doctor of Philosophy in Computer Science and Technology is the first PhD programme offered by the School of Computing and Data Science (SCDS). It provides a platform to nurture talents in innovative and cutting-edge research for the next generation. This PhD programme is open to all potential students with diverse computing backgrounds, include but not limited to Information Systems, Cybersecurity, Data Science, Artificial Intelligence, Computer Science, Computer Engineering, Digital Media Technology, and Software Engineering. Students are encouraged to participate in international competitions and to publish their research in reputable journals and conferences.":"计算机科学与技术博士是计算与数据科学学院（SCDS）开办的首个博士课程，为培养下一代创新与前沿研究人才提供平台。本博士课程开放给所有具备不同计算机背景的潜在学生，包括但不限于信息系统、网络安全、数据科学、人工智能、计算机科学、计算机工程、数字媒体技术及软件工程。学校鼓励学生参加国际竞赛，并在知名期刊和学术会议上发表研究成果。",
