"Industrial Automation Engineer":"工业自动化工程师",
"Industrial Design is the professional practice of designing products used by millions of people around the world every day; industrial designers focus on the product’s appearance and value on top of how it’s manufactured and user experience. In the first and second year, students are exposed to various skills from manual sketching, digital sketching to model making, realising their concept design into reality. Students specialise in 1 main area in their final year: Product Design, Furniture Design, Transport Design or Sustainable Design.":"工业设计是一门为全球数以百万计的人每天使用的产品进行设计的专业实践；工业设计师除了关注产品的制造方式与用户体验，也注重产品的外观与价值。在第一和第二年，学生将接触从手绘草图、数码草图到模型制作等各种技能，把概念设计化为现实。学生在最后一年专攻一个主要领域：产品设计、家具设计、交通工具设计或可持续设计。",
"Industrial Designer":"工业设计师",
"Industrial Training":"工业实习",
