"Master of Science in Computer Science and Technology":"计算机科学与技术理学硕士",
"Master of Science in Computer Science and Technology, offered by the School of Computing and Data Science (SCDS), is designed to equip students from diverse computing backgrounds with advanced knowledge in areas such as AI, cybersecurity, software technology, and more. The program emphasizes hands-on learning through practical projects, research, and collaboration with industry partners, preparing students for successful careers in academia and technology sectors. Students are encouraged to participate in international competitions and publish their research in reputable journals and conferences.":"计算机科学与技术理学硕士由计算与数据科学学院（SCDS）开办，旨在让来自不同计算机背景的学生掌握人工智能、网络安全、软件技术等领域的进阶知识。课程注重通过实践项目、研究及与业界伙伴合作进行实践学习，为学生在学术界和科技领域的成功事业做好准备。学校鼓励学生参加国际竞赛，并在知名期刊和学术会议上发表研究成果。",
