"Mechatronic Engineer":"机电一体化工程师",
"Mechatronic Engineering is concerned with the creation, design and building of intelligent machines; this new breed of engineer has to master skills in mechanical, electronic and computer engineering and work in a hybrid manner. The programme provides a study of basic engineering sciences and fundamentals of mechanical, electrical, electronics and computer engineering, enabling students to integrate these four disciplines. It develops the technical skills to design, analyse and test “intelligent” products or processes that incorporate suitable controller, sensor and mechatronic devices for robotics and automation.":"机电一体化工程涉及智能机器的创造、设计与建造；这类新型工程师须掌握机械、电子及计算机工程技能，并以跨领域方式工作。本课程研习基础工程科学以及机械、电机、电子与计算机工程的基础知识，使学生能够整合这四个学科。课程培养学生设计、分析及测试\"智能\"产品或流程的技术能力，这些产品或流程融合了适用于机器人与自动化的控制器、传感器及机电设备。",
