"Occupational therapists evaluate and treat clients with physical, psychosocial or developmental impairments or disabilities, so that their home, workplace and community are accessible and safe. The programme covers therapeutic techniques, orthotics and prosthetics, assistive devices and environmental modifications, with 1,360 hours of practicum from year 1.":"职能治疗师为有身体、心理社会或发育障碍的人士进行评估与治疗，让他们的家居、工作场所及社区方便出入且安全。课程涵盖治疗技术、矫形器与义肢、辅助器具及环境改造，并从第一年起提供 1,360 小时的实习。",
