"Our 12-month Foundation Programme is designed to prepare those with SPM, 'O' Levels or similar qualifications with the knowledge and skills to progress into the first year of a degree of their choice. On completion of the Foundation Programme, you will be able to make an informed decision about your interest and pursue your degree of choice. During the Foundation Programme, you are able to choose different routes depending on your area of interest, allowing you to progress onto a specific degree programme at APU related to this area or other relevant areas.":"我们为期12个月的预科课程，旨在让持有 SPM、O-Level 或同类资格的学生掌握所需知识与技能，以升读所选学位课程的第一年。完成预科课程后，你将能对自己的兴趣作出明智决定，并攻读心仪的学位。在预科课程期间，你可根据兴趣领域选择不同方向，从而升读 APU 与该领域或其他相关领域有关的特定学位课程。",
"Our Bachelor in Banking and Finance (Hons) is an ideal and outstanding programme for those who wish to engage in financial services industry or government sectors, particularly in banking and central banking. Students on the course also have the flexibility of developing and building their specialised knowledge in areas such as Financial Planning as well as Investment & Risk Management. There is high global demand for well-trained Banking & Finance individuals in banking, finance, education, as well as government sectors.":"我们的银行与金融荣誉学士（Bachelor in Banking and Finance (Hons)）是一项理想而出色的课程，适合有意投身金融服务业或政府部门（尤其是银行及中央银行）的学生。修读本课程的学生也可灵活发展并建立在理财规划以及投资与风险管理等领域的专业知识。全球对训练有素的银行与金融人才需求殷切，遍及银行、金融、教育及政府部门。",
"Our Journalism programme has a proud history that dates back to 1922, when Xiamen University first introduced its Journalism studies. At XMUM, the programme is designed to provide a balanced blend of academic knowledge and hands-on-experience, equipping students with a well-rounded understanding of the media's role in society and the challenges of international and cross-cultural communication. The curriculum covers essential skills in journalistic reporting, storytelling, broadcast journalism, and production techniques, and aims to develop students' professional ethics, critical thinking, and sense of social responsibility.":"我们的新闻学课程历史悠久，可追溯至1922年，当时 厦门大学 首次开办新闻学教育。在 XMUM，本课程旨在平衡结合学术知识与实践经验，使学生全面了解媒体在社会中的角色，以及国际与跨文化传播所面临的挑战。课程涵盖新闻报道、叙事、广播新闻及制作技术等核心技能，并致力于培养学生的职业道德、批判性思维与社会责任感。",
"Our graduates will have the opportunities to work in many industries, including":"我们的毕业生将有机会在多个产业就业，包括",
