"Petroleum engineers define and develop petroleum reservoirs, and produce oil and gas with maximum profitable recovery. The programme combines petroleum, gas and exploration engineering to cater for the ever-demanding oil and gas industry, and develops the ability to apply engineering principles to the design, development and operation of systems for locating, extracting, processing and refining crude petroleum and natural gas, including related environmental and safety systems. Petroleum engineering software applications are fully incorporated into the curriculum.":"石油工程师负责界定与开发油藏，并以最大的获利采收率生产石油和天然气。本课程结合石油、天然气与勘探工程，以满足需求日益严苛的石油与天然气行业，并培养学生将工程原理应用于原油及天然气勘探定位、开采、加工与炼制系统（包括相关环境与安全系统）之设计、开发及运作的能力。石油工程软件应用已全面融入课程之中。",
