"Preferred disciplines: Management, Human Resource, Information Technology, Early Childhood, Accounting, Hotel Management, Retail Management, Business":"优先学科：管理、人力资源、资讯科技、幼儿教育、会计、酒店管理、零售管理、商业",
"Preferred fields: Agricultural Sciences, Sciences (Chemistry, Biotech), Engineering (Chemical, Mechanical, Civil, Electrical & Electronics), Accountancy, Information Technology, Architecture, Real Estate Management, Town & Regional Planning":"优先领域：农业科学、科学（化学、生物科技）、工程（化工、机械、土木、电气与电子）、会计、信息技术、建筑、房地产管理、城乡规划",
"Preferred fields: Civil Engineering, Quantity Surveying, Architecture, Building Management, Business Administration/Marketing/Communication/Accounting, Human Resource Management, Event Management, Hospitality/Hotel Management, Agriculture":"优先领域：土木工程、估价、建筑、建筑管理、工商管理/市场营销/传播/会计、人力资源管理、活动管理、酒店管理、农业",
