"Preferred fields: digital skills (computer science, IT, data analytics, digitalisation, AI, technology design, programming, cyber security); risk management, actuarial science, banking & finance, statistics, economics, accounting and sustainability also considered":"优先领域：数字技能（计算机科学、资讯科技、数据分析、数字化、人工智能、科技设计、编程、网络安全）；风险管理、精算、银行与金融、统计、经济、会计及可持续发展也会考虑",
