"to see if you meet these requirements.":"以确认您是否符合这些要求。",
"• (MUET Band 2 is required for all Malaysian Students)":"• （所有马来西亚学生须具备 MUET Band 2）",
"• (i) Additional Mathematics*** - a credit in SPM or the equivalent; OR (ii) Mathematics and any 1 Science/Technology/Engineering subject - a credit in SPM or the equivalent AND pass a Mathematics placement test organised by XMUM before joining the programme":"• (i) 高级数学*** - SPM 或同等学历考获优等；或 (ii) 数学及任何 1 科理科／工艺／工程科目 - SPM 或同等学历考获优等，并在入读课程前通过 XMUM 举办的数学分级测试",
"• * Candidates with a CGPA of less than 2.5 but more than 2.0 may be accepted subject to a stringent internal evaluation process.":"• * CGPA 低于 2.5 但高于 2.0 的考生，须经严格的内部评估程序后方可能获录取。",
"• * Strong Mathematics would be an added advantage.":"• * 数学成绩优秀者更具优势。",
"• ** Candidates with a CGPA of less than 2.75 but more than 2.5 may be accepted subject to a stringent internal evaluation process.":"• ** CGPA 低于 2.75 但高于 2.5 的考生，须经严格的内部评估程序后方可能获录取。",
"• *** The requirement for the Additional Mathematics at SPM level can be exempted if the Foundation/Matriculation or its equivalent offers a Mathematics course that is of a similar or higher level compared to the Additional Mathematics at SPM level.":"• *** 若预科／大学先修班或同等课程设有与 SPM 高级数学同等或更高程度的数学科目，则可豁免 SPM 程度高级数学的要求。",
"• *Rigorous assessment can be done through interviews, portfolios, written tests, or any form of assessment. If the assessment fulfils the requirements, the candidates can be exempted from taking the prerequisite courses.":"• *严格评估可通过面试、作品集、笔试或任何形式的评估进行。若评估符合要求，申请者可豁免修读先修课程。",
"• 2 Passes in A-Level and with a Credit in Mathematics at SPM/ O-Level/ IGCSE or equivalent.":"• A-Level 2 科及格，且 SPM/ O-Level/ IGCSE 或同等学历数学考获优等。",
"• 2 Passes in A-Level and with a Pass in Mathematics at SPM/ O-Level/ IGCSE or equivalent.":"• A-Level 2 科及格，且 SPM/ O-Level/ IGCSE 或同等学历数学及格。",
"• 2 Passes in A-Level in Science stream with a Pass in Mathematics and one Science or ICT subject. OR":"• A-Level 理科组 2 科及格，且数学及一科理科或 ICT 科目及格。或",
"• 2 Passes in A-Level in any 2 subjects, and a Credit in English at SPM/O-Level/ IGCSE or its equivalent.":"• A-Level 任何2科及格，且 SPM/O-Level/ IGCSE 英文优等或同等学历。",
"• 2 Passes in A-Level in any 2 subjects, and a Credit in Mathematics and a Pass in English at SPM/O-Level/ IGCSE or its equivalent.":"• A-Level 任何2科及格，且 SPM/O-Level/ IGCSE 数学优等、英文及格或同等学历。",
"• 2 Passes in A-Level in any 2 subjects, and a Credit in Mathematics at SPM/O-Level/ IGCSE or its equivalent.":"• A-Level 任何2科及格，且 SPM/O-Level/ IGCSE 数学优等或同等学历。",
"• 2 Passes in A-Level including Mathematics and Physics (or Chemistry), and a Credit in Mathematics and Physics (or Chemistry) at SPM/O-Level/IGCSE or its equivalent.":"• A-第二级科及格，包括数学和物理（或化学），且 SPM/O-Level/IGCSE 数学和物理（或化学）优等或同等学历。",
"• 2 Passes in A-Level with a Credit in Additional Mathematics at SPM/ IGCSE/ O-Level or equivalent. OR":"• A-Level 2 科及格，且 SPM/ IGCSE/ O-Level 或同等学历高级数学考获优等。或",
"• 2 Passes in A-Level with a Credit in Mathematics and Science or ICT subjects at SPM/ IGCSE/ O-Level or equivalent. Candidates need to do a Pre-Requisite module in Further Mathematics or equivalent in the first semester of Degree Programme.":"• A-Level 2 科及格，且 SPM/ IGCSE/ O-Level 或同等学历数学及理科或 ICT 科目考获优等。考生须在学位课程第一学期修读高级数学（Further Mathematics）先修单元或同等单元。",
"• 2 Passes in A-Level with a Pass in English and Mathematics at SPM/ O-Level/ IGCSE or its equivalent.*":"• A-Level 2 科及格，且 SPM/ O-Level/ IGCSE 或同等学历英文和数学及格。*",
"• 2 Passes in A-Level with a Pass in English at SPM/ O-Level/ IGCSE or its equivalent.":"• A-Level 2 科及格，且 SPM/ O-Level/ IGCSE 或同等学历英文及格。",
"• 2 Passes in A-Level.":"• A-Level 2 科及格。",
"• 2 Passes in STPM in Science stream with minimum Grade C (GPA 2.0) in Mathematics and one Science or ICT Subject. OR":"• STPM 理科组 2 科及格，数学及一科理科或 ICT 科目至少 C 等级（GPA 2.0）。或",
"• 2 Passes in STPM with a minimum Grade C (GP 2.0) and a Credit in English at SPM Level or its equivalent.":"• STPM 2科及格，最低 C 等级（GP 2.0），且 SPM 英文优等或同等学历。",
"• 2 Passes in STPM with a minimum Grade C (GP 2.0) and a Pass in English and Mathematics at SPM Level or its equivalent.*":"• STPM 2 科及格，至少考获 C 等级（GP 2.0），且 SPM 程度或同等学历英文和数学及格。*",
"• 2 Passes in STPM with a minimum Grade C (GP 2.0) in Mathematics and Physics (or Chemistry), and a Credit in Mathematics and Physics (or Chemistry) at SPM Level or its equivalent.":"• STPM 2科及格，数学和物理（或化学）最低 C 等级（GP 2.0），且 SPM 数学和物理（或化学）优等或同等学历。",
"• 2 Passes in STPM with a minimum Grade C (GP 2.0).":"• STPM 2科及格，最低 C 等级（GP 2.0）。",
"• 2 Passes in STPM with a minimum Grade C+ (GP 2.33) and a Credit in Mathematics and a Pass in English at SPM Level or its equivalent.":"• STPM 2科及格，最低 C+ 等级（GP 2.33），且 SPM 数学优等、英文及格或同等学历。",
"• 2 Passes in STPM with a minimum Grade C+ (GP 2.33) and a Credit in Mathematics at SPM Level or its equivalent.":"• STPM 2科及格，最低 C+ 等级（GP 2.33），且 SPM 数学优等或同等学历。",
"• 2 Passes in STPM with minimum Grade C (CGPA 2.0) in any subject with a Credit in Mathematics at SPM.":"• STPM 任何 2 科及格，至少 C 等级（CGPA 2.0），且 SPM 数学考获优等。",
"• 2 Passes in STPM with minimum Grade C (CGPA 2.0) in any subject with a Pass in Mathematics at SPM.":"• STPM 任何科目 2 科及格，至少考获 C 等级（CGPA 2.0），且 SPM 数学及格。",
"• 2 Passes in STPM with minimum Grade C (GPA 2.0) in any subject with a credit in Additional Mathematics at SPM. OR":"• STPM 任何 2 科及格，至少 C 等级（GPA 2.0），且 SPM 高级数学考获优等。或",
"• 2 Passes in STPM with minimum Grade C (GPA 2.0) in any subject with a credit in Mathematics and any one Science or ICT subjects at SPM. Candidates need to do a Pre-Requisite module in Further Mathematics or equivalent in the first semester of Degree Programme.":"• STPM 任何 2 科及格，至少 C 等级（GPA 2.0），且 SPM 数学及任何一科理科或 ICT 科目考获优等。考生须在学位课程第一学期修读高级数学（Further Mathematics）先修单元或同等单元。",
