"• i. A Bachelor's Degree in Chemical Engineering or a related discipline with a minimum Cumulative Grade Point Average (CGPA) of 2.75 or":"• i. 拥有化学工程或相关学科的学士学位，累积平均绩点（CGPA）至少 2.75；或",
"• i. A Bachelor's Degree with a minimum CGPA of 2.75 or":"• i. 拥有学士学位，CGPA 至少 2.75；或",
"• i. A Bachelor's degree (Level 6, MQF) in the field or related field with a minimum CGPA of 2.75 or equivalent as accepted by the HEP Senate; OR":"• i. 拥有该领域或相关领域的学士学位（MQF 第 6 级），CGPA 至少 2.75 或同等成绩，并获高等教育机构（HEP）校务委员会（Senate）接受；或",
"• i. A Master's Degree in related science or engineering discipline or":"• i. 拥有相关理科或工程学科的硕士学位；或",
"• ii. A Bachelor's Degree in Chemical Engineering or a related discipline with a minimum CGPA of 2.50 but below 2.75 will be subjected to rigorous internal assessment or":"• ii. 拥有化学工程或相关学科的学士学位，CGPA 至少 2.50 但低于 2.75，须经严格的内部评估；或",
"• ii. A Bachelor's Degree with a minimum CGPA of 2.50 but below 2.75 will be subject to internal assessment or":"• ii. 拥有学士学位，CGPA 至少 2.50 但低于 2.75，须经内部评估；或",
"• ii. A Bachelor's degree (Level 6, MQF) in the field or related field with a minimum CGPA of 2.50 and not meeting CGPA of 2.75 can be accepted, subject to rigorous internal assessment;":"• ii. 拥有该领域或相关领域的学士学位（MQF 第 6 级），CGPA 至少 2.50 但未达 2.75，须经严格的内部评估方可被录取；",
"• ii. Any other equivalent qualifications recognised by the Malaysian Government, show evidence of adequate related research or work experience and accepted by the Senate":"• ii. 任何其他获马来西亚政府承认的同等学历，并能证明具备足够的相关研究或工作经验，且获校务委员会（Senate）接受",
"• ii. Any other equivalent qualifications recognised by the Malaysian Government, show evidence of adequate related research or work experience and accepted by the Senate; or":"• ii. 任何其他获马来西亚政府承认的同等学历，并能证明具备足够的相关研究或工作经验，且获校务委员会（Senate）接受；或",
"• iii. A Bachelor's Degree in Chemical Engineering or a related discipline with a minimum CGPA below 2.50, can be accepted subjected to a minimum of five years of relevant working experience and rigorous internal assessment or":"• iii. 拥有化学工程或相关学科的学士学位，CGPA 低于 2.50，须具备至少五年相关工作经验并经严格的内部评估方可被录取；或",
"• iii. A Bachelor's Degree with a minimum CGPA below 2.50, can be accepted subject to a minimum of 5 years of relevant working experience or":"• iii. 拥有学士学位，CGPA 低于 2.50，须具备至少 5 年相关工作经验方可被录取；或",
"• iii. A Bachelor's degree (Level 6, MQF) in the field or related field with a minimum CGPA of 2.00 and not meeting CGPA of 2.50 can be accepted, subject to a minimum of 5 years relevant working experience and rigorous internal assessment;":"• iii. 拥有该领域或相关领域的学士学位（MQF 第 6 级），CGPA 至少 2.00 但未达 2.50，须具备至少 5 年相关工作经验并经严格的内部评估方可被录取；",
"• iii. Bachelor's Degree candidates who are registered for Master's Degree programmes may apply to convert to the Doctoral Degree programmes within one year full-time and two years for part-time candidates, having shown competency and capability in conducting research at doctoral level through rigorous internal evaluation and approval of the Senate":"• iii. 已注册硕士学位课程的学士学位持有者，可申请转读博士学位课程（全日制须在一年内，部分时间制须在两年内），前提是已展现在博士层次开展研究的能力与才干，并通过严格的内部评估及获校务委员会（Senate）批准",
"• iv. Any other equivalent qualifications recognised by the Malaysian Government and accepted by the Senate":"• iv. 任何其他获马来西亚政府承认并获校务委员会（Senate）接受的同等学历",
"• iv. Candidates without a qualification in Chemical Engineering or relevant working experience must undergo appropriate prerequisite courses and meet the minimum CGPA based on i to iii or":"• iv. 未具备化学工程资格或相关工作经验的申请者，须修读适当的先修课程，并符合第 i 至 iii 项的最低 CGPA 要求；或",
"• iv. Candidates without a related qualification in the field/s or working experience in the relevant fields must undergo appropriate prerequisite courses determined by the HEP and meet the minimum CGPA based on (i) to (iii)":"• iv. 未具备该领域相关资格或相关领域工作经验的申请者，须修读高等教育机构（HEP）指定的适当先修课程，并符合第 (i) 至 (iii) 项的最低 CGPA 要求",
"• v. Any other equivalent qualifications recognised by the Malaysian Government and accepted by the Senate.":"• v. 任何其他获马来西亚政府承认并获校务委员会（Senate）接受的同等学历。"
